from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom-Header"] = "CustomValue"
    return response

@app.get("/test-annotated")
def test_annotated(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "success"}

@app.get("/test-default")
def test_default(response: Response = Depends(modify_response)):
    return {"message": "success"}

@app.get("/test-regular")
def test_regular(response: Response):
    return {"message": "success"}

client = TestClient(app)

def test_annotated():
    response = client.get("/test-annotated")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_default():
    response = client.get("/test-default")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_regular():
    response = client.get("/test-regular")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_annotated()
        print("test_annotated passed")
        test_default()
        print("test_default passed")
        test_regular()
        print("test_regular passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

from fastapi import FastAPI, Depends, Response, Query
from fastapi.testclient import TestClient
from typing import Annotated
import pytest

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom-Header"] = "CustomValue"
    return response

@app.get("/test-annotated")
def test_annotated(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "success"}

@app.get("/test-default")
def test_default(response: Response = Depends(modify_response)):
    return {"message": "success"}

@app.get("/test-regular")
def test_regular(response: Response):
    return {"message": "success"}

client = TestClient(app)

def test_annotated():
    response = client.get("/test-annotated")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_default():
    response = client.get("/test-default")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_regular():
    response = client.get("/test-regular")
    assert response.status_code == 200

def test_invalid_query():
    # This should fail during app initialization or when the route is analyzed
    # Since FastAPI analyzes routes at startup, we can try to create a new app
    try:
        app_invalid = FastAPI()
        @app_invalid.get("/invalid")
        def invalid(response: Response = Query(...)):
            return {"message": "success"}

        # Trigger analysis by creating a TestClient or calling the route
        TestClient(app_invalid).get("/invalid")
        print("test_invalid_query failed: it should have raised AssertionError")
    except AssertionError as e:
        print(f"test_invalid_query passed: caught expected AssertionError: {e}")
    except Exception as e:
        print(f"test_invalid_query caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    try:
        test_annotated()
        print("test_annotated passed")
        test_default()
        print("test_default passed")
        test_regular()
        print("test_regular passed")
        test_invalid_query()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e
